"""FastAPI 主应用 — 应用入口、生命周期管理和 WebSocket 端点。

路由按功能拆分到 routes/ 子包:
- routes/system.py  — /api/system/*     系统管理
- routes/task.py    — /api/task/*       任务执行
- routes/game.py    — /api/game/*       游戏状态查询
- routes/ops.py     — /api/expedition/* /api/build/* 等操作
- routes/health.py  — /api/health       健康检查

WebSocket 端点保留在此文件:
- WS  /ws/logs  — 实时日志流
- WS  /ws/task  — 任务状态更新

使用方式:
    uvicorn autowsgr.server.main:app --host 0.0.0.0 --port 8000
"""

from __future__ import annotations

import asyncio
import hmac
import json
import os
from contextlib import asynccontextmanager, suppress
from enum import StrEnum
from typing import Any

from fastapi import FastAPI, Request, WebSocket, WebSocketDisconnect
from fastapi.encoders import jsonable_encoder
from fastapi.exceptions import RequestValidationError
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException

from autowsgr.infra.config import api_docs_enabled, resolve_api_token
from autowsgr.infra.logger import (
    disable_ws_log_sink,
    enable_ws_log_sink,
    get_logger,
)
from autowsgr.server.errors import ApiError, ErrorCode, api_error, fallback_error_code
from autowsgr.server.task_manager import task_manager
from autowsgr.server.ws_manager import log_ws_manager, task_ws_manager


_log = get_logger('server')

# /ws/logs 的日志转发队列。日志由 loguru 在任意线程产生，先经
# call_soon_threadsafe 入队，再由事件循环里的单消费者广播（5.6/R31）。
_LOG_WS_QUEUE_MAXSIZE = 1000
_LOG_WS_SINK_LEVEL = 'INFO'


# ═══════════════════════════════════════════════════════════════════════════════
# 全局状态
# ═══════════════════════════════════════════════════════════════════════════════

# GameContext 全局引用 (启动后设置)
_ctx: Any = None


class SystemState(StrEnum):
    """系统生命周期状态（5.4）。

    ``IDLE`` 是「尚未启动 / 已完全停止」，与两个过渡态区分开：任务接口
    在 IDLE 下提示先启动系统，在 STARTING/STOPPING 下提示稍候。
    """

    IDLE = 'idle'
    STARTING = 'starting'
    READY = 'ready'
    STOPPING = 'stopping'


_system_state: SystemState = SystemState.IDLE

_TRANSITION_STATE_MESSAGES = {
    SystemState.STARTING: '系统正在启动，请稍候',
    SystemState.STOPPING: '系统正在停止，请稍候',
}
_TRANSITION_STATE_ERROR_CODES = {
    SystemState.STARTING: ErrorCode.SYSTEM_STARTING,
    SystemState.STOPPING: ErrorCode.SYSTEM_STOPPING,
}
_SYSTEM_NOT_STARTED_MESSAGE = '系统未启动，请先调用 POST /api/system/start'

# 5.3：超时强制断开的硬上界。30s 协作式等待 + 4s 断开 = 34s < 35s 验收线。
_FORCE_DISCONNECT_TIMEOUT_SECONDS = 4.0

# 序列化系统上下文的发布、任务准入和回收。
lifecycle_lock = asyncio.Lock()


def get_system_state() -> SystemState:
    """当前系统生命周期状态。"""
    return _system_state


def set_system_state(state: SystemState) -> None:
    """更新系统生命周期状态（仅生命周期路由调用）。"""
    global _system_state
    _system_state = state


def lifecycle_busy_error() -> ApiError | None:
    """启动/停止过渡中时返回 503；必须在抢 ``lifecycle_lock`` 之前调用。"""
    message = _TRANSITION_STATE_MESSAGES.get(_system_state)
    if message is None:
        return None
    return api_error(
        503,
        _TRANSITION_STATE_ERROR_CODES[_system_state],
        message,
        headers={'Retry-After': '1'},
    )


def ensure_system_ready() -> None:
    """任务准入：非 ``ready`` 立即 503，不排队等待 ``lifecycle_lock``（5.4）。"""
    if _system_state is SystemState.READY:
        return
    message = _TRANSITION_STATE_MESSAGES.get(
        _system_state,
        _SYSTEM_NOT_STARTED_MESSAGE,
    )
    code = _TRANSITION_STATE_ERROR_CODES.get(
        _system_state,
        ErrorCode.SYSTEM_NOT_READY,
    )
    raise api_error(
        503,
        code,
        message,
        headers={'Retry-After': '1'},
    )


# 5.1：状态接口对探活的硬截止。控制器内部「帧窗口 1.5s + ADB 探活 0.8s」
# 已留余量，这里再兜一层，保证 adb 卡死时 /api/system/status 仍在 3s 内返回。
_EMULATOR_PROBE_DEADLINE_SECONDS = 2.5


def get_context() -> Any:
    """获取全局 GameContext。"""
    if _ctx is None:
        raise RuntimeError('系统未启动，请先调用 POST /api/system/start')
    return _ctx


def bind_context_observers(ctx: Any) -> None:
    """把核心上下文里的可观测状态桥接到任务 WS 频道。

    - 5.9：``GameContext`` 在战斗线程里同步更新掉落计数，本身不认识
      FastAPI；注入一个只做线程安全投递的 sink，日志级别再高也丢不掉。
    - 4.5：页面识别 / 子状态 / 战斗阶段的变化通过 ``ui_state_sink`` 推给
      前端；``ui/page.py`` 的全局观察者负责把每次识别结果接到
      ``ctx.observe_page``。两处都只投递，不改核心流程。
    """
    if ctx is None:
        return

    if hasattr(ctx, 'loot_update_sink'):

        def _publish_loot_update(loot_count: int, ship_count: int) -> None:
            task_manager.publish_loot_update(
                loot_count=loot_count,
                ship_count=ship_count,
            )

        try:
            ctx.loot_update_sink = _publish_loot_update
        except Exception as exc:  # pragma: no cover - 只防御不可变/带 slots 的上下文
            _log.warning('[Server] 绑定掉落事件 sink 失败: {}', exc)

    if hasattr(ctx, 'ui_state_sink') and callable(getattr(ctx, 'observe_page', None)):
        try:
            ctx.ui_state_sink = task_manager.publish_ui_state
        except Exception as exc:  # pragma: no cover - 同上
            _log.warning('[Server] 绑定 UI 状态 sink 失败: {}', exc)
        else:
            from autowsgr.ui.page import set_page_observer

            set_page_observer(ctx.observe_page)


def unbind_context_observers(ctx: Any) -> None:
    """释放上下文时摘掉全局页面观察者，避免识别回调指向已销毁的上下文。"""
    from autowsgr.ui.page import set_page_observer

    set_page_observer(None)
    if ctx is not None and hasattr(ctx, 'ui_state_sink'):
        try:
            ctx.ui_state_sink = None
        except Exception:  # pragma: no cover
            pass


async def is_emulator_alive() -> bool:
    """真实探活：模拟器当前是否仍然可用（5.1）。

    ``_ctx is not None`` 只说明曾经连接成功，模拟器被关掉后它仍为真。
    这里改为询问控制器的 ``is_alive()``（最近帧时间戳 / socket 状态 /
    轻量 ADB 兜底探活），并放到工作线程执行，避免阻塞事件循环。
    没有 ``is_alive`` 的旧控制器退回「已连接即存活」语义。
    """
    ctx = _ctx
    if ctx is None:
        return False
    ctrl = getattr(ctx, 'ctrl', None)
    if ctrl is None:
        return False
    probe = getattr(ctrl, 'is_alive', None)
    if probe is None:
        return True
    try:
        return bool(
            await asyncio.wait_for(
                asyncio.to_thread(probe),
                timeout=_EMULATOR_PROBE_DEADLINE_SECONDS,
            )
        )
    except TimeoutError:
        _log.warning(
            '[Server] 模拟器探活超时 (>{}s)，判定为断开',
            _EMULATOR_PROBE_DEADLINE_SECONDS,
        )
        return False
    except Exception as exc:  # noqa: BLE001 - 探活异常一律视为断开
        _log.warning('[Server] 模拟器探活失败: {}', exc)
        return False


def disconnect_context(ctx: Any) -> None:
    """断开设备连接（阻塞调用，需在工作线程中执行）。"""
    ctrl = getattr(ctx, 'ctrl', None)
    if ctrl is None:
        return
    try:
        ctrl.disconnect()
    except Exception as exc:  # noqa: BLE001 - 清理失败不能阻断上下文释放
        _log.warning('[Server] 断开设备连接失败: {}', exc)


def invalidate_context(ctx: Any) -> None:
    """把上下文标记为失效，让残留 worker 的后续设备访问快速失败（5.3）。"""
    try:
        ctx.invalidated = True
    except Exception as exc:  # pragma: no cover - 只防御 __slots__ 上下文
        _log.warning('[Server] 标记上下文失效失败: {}', exc)
    stop_event = getattr(ctx, 'stop_event', None)
    if stop_event is not None:
        try:
            stop_event.set()
        except Exception as exc:  # pragma: no cover - 信号异常不能阻断清理
            _log.warning('[Server] 设置上下文停止信号失败: {}', exc)


async def release_context() -> None:
    """断开设备并释放全局上下文（幂等）。

    停止系统与进程退出都走这里，确保 scrcpy 的 socket、解码线程和
    设备端进程不会随 ``_ctx`` 置空一起泄漏。
    """
    global _ctx
    ctx = _ctx
    if ctx is None:
        return
    try:
        invalidate_context(ctx)
        await asyncio.to_thread(disconnect_context, ctx)
    finally:
        unbind_context_observers(ctx)
        _ctx = None


async def force_release_context(
    timeout: float = _FORCE_DISCONNECT_TIMEOUT_SECONDS,
) -> bool:
    """5.3 超时兜底：立即摘除全局上下文，限时强制断开设备。

    与 ``release_context`` 的差别是**先**把 ``_ctx`` 置空：即使
    ``disconnect()`` 卡住，也不会再暴露一个半死上下文。返回断开调用是否
    在限时内完成；超时后工作线程可能仍在后台，但上下文已标记失效，其
    后续设备调用会失败。
    """
    global _ctx
    ctx = _ctx
    _ctx = None
    if ctx is None:
        return True
    unbind_context_observers(ctx)
    invalidate_context(ctx)
    try:
        await asyncio.wait_for(
            asyncio.to_thread(disconnect_context, ctx),
            timeout=timeout,
        )
        return True
    except TimeoutError:
        _log.error(
            '[Server] 强制断开设备超时 (>{}s)，上下文已丢弃',
            timeout,
        )
        return False
    except Exception as exc:  # noqa: BLE001 - 兜底路径不能把异常带回路由
        _log.warning('[Server] 强制断开设备失败: {}', exc)
        return False


# ═══════════════════════════════════════════════════════════════════════════════
# 生命周期管理
# ═══════════════════════════════════════════════════════════════════════════════


async def _log_ws_pump(queue: asyncio.Queue[dict[str, Any]]) -> None:
    """串行消费日志队列并广播到 ``/ws/logs``。

    单消费者保证日志顺序；``broadcast`` 内部已经并发发送并限时剔除
    失效连接，因此这里即使遇到死连接也不会阻塞后续日志。
    """
    while True:
        payload = await queue.get()
        try:
            await log_ws_manager.send_log(
                level=str(payload.get('level') or 'info'),
                message=str(payload.get('message') or ''),
                channel=str(payload.get('channel') or ''),
                timestamp=payload.get('timestamp'),
                source=payload.get('source'),
            )
        except Exception as exc:  # noqa: BLE001 - 日志转发失败不能拖垮应用
            _log.debug('[WS:logs] 日志广播失败: {}', exc)
        finally:
            queue.task_done()


@asynccontextmanager
async def lifespan(app: FastAPI):  # noqa: ARG001
    """应用生命周期管理。"""
    # 启动时: 设置事件循环引用
    loop = asyncio.get_running_loop()
    task_manager.set_loop(loop)
    _log.info('[Server] HTTP Server 已启动')

    # 5.6/R31：把 loguru 的 INFO 及以上日志接到 /ws/logs。
    # 回调可能来自任意工作线程，只做 call_soon_threadsafe 入队。
    log_queue: asyncio.Queue[dict[str, Any]] = asyncio.Queue(
        maxsize=_LOG_WS_QUEUE_MAXSIZE
    )

    def _put_log(payload: dict[str, Any]) -> None:
        try:
            log_queue.put_nowait(payload)
        except asyncio.QueueFull:
            # 客户端消费不过来时丢弃新日志，绝不阻塞业务线程。
            pass

    def _enqueue_log(payload: dict[str, Any]) -> None:
        if not log_ws_manager.has_connections():
            return
        try:
            loop.call_soon_threadsafe(_put_log, payload)
        except RuntimeError:
            # 事件循环已关闭（进程退出窗口）。
            pass

    log_pump_task = asyncio.create_task(
        _log_ws_pump(log_queue),
        name='ws-log-pump',
    )
    enable_ws_log_sink(_enqueue_log, level=_LOG_WS_SINK_LEVEL)

    try:
        yield
    finally:
        # 关闭时: 先停日志转发，再清理资源。
        disable_ws_log_sink()
        log_pump_task.cancel()
        with suppress(asyncio.CancelledError):
            await log_pump_task

        if _ctx is not None:
            _log.info('[Server] 断开模拟器连接')
            await release_context()
        _log.info('[Server] HTTP Server 已关闭')


