# 6.1/R17：只有显式开启 AUTOWSGR_API_DOCS 才暴露文档端点。
_API_DOCS_ENABLED = api_docs_enabled()

app = FastAPI(
    title='AutoWSGR HTTP API',
    description='战舰少女R 自动化脚本 HTTP 接口',
    version='1.0.0',
    lifespan=lifespan,
    docs_url='/docs' if _API_DOCS_ENABLED else None,
    redoc_url='/redoc' if _API_DOCS_ENABLED else None,
    openapi_url='/openapi.json' if _API_DOCS_ENABLED else None,
)


# ═══════════════════════════════════════════════════════════════════════════════
# 6.1/R17：API token 鉴权
# ═══════════════════════════════════════════════════════════════════════════════

_API_PATH = '/api'
_BEARER_SCHEME = 'bearer'
_WS_TOKEN_PARAM = 'token'


def _is_api_path(path: str) -> bool:
    """``/api`` 与 ``/api/*`` 需要鉴权；静态文件和 WebSocket 单独判断。"""
    return path == _API_PATH or path.startswith(_API_PATH + '/')


def _extract_bearer_token(header_value: str | None) -> str | None:
    """从 ``Authorization`` 头里取 Bearer token，格式不对返回 None。"""
    if not header_value:
        return None
    scheme, _, value = header_value.partition(' ')
    if scheme.strip().lower() != _BEARER_SCHEME:
        return None
    token = value.strip()
    return token or None


def _token_matches(supplied: str | None, expected: str) -> bool:
    """常量时间比较，避免按字节比较泄漏 token 前缀。"""
    if not supplied or not expected:
        return False
    return hmac.compare_digest(supplied, expected)


def unauthorized_response(message: str = '缺少或无效的访问令牌') -> JSONResponse:
    """401 也走 5.10 的统一错误信封，前端无需特判。"""
    return JSONResponse(
        status_code=401,
        content={
            'success': False,
            'data': None,
            'message': None,
            'error': message,
            'error_code': str(ErrorCode.UNAUTHORIZED),
            'detail': message,
        },
        headers={'WWW-Authenticate': 'Bearer'},
    )


async def require_api_token(request: Request, call_next: Any) -> Any:
    """拦截所有 ``/api/*``：没有有效 Bearer token 一律 401。

    CORS 预检（OPTIONS）由外层 CORSMiddleware 处理，这里跳过以免浏览器
    因为拿不到预检响应而把正常请求判成网络错误。
    """
    if request.method == 'OPTIONS' or not _is_api_path(request.url.path):
        return await call_next(request)
    supplied = _extract_bearer_token(request.headers.get('authorization'))
    if not _token_matches(supplied, resolve_api_token()):
        return unauthorized_response()
    return await call_next(request)


app.middleware('http')(require_api_token)

# CORS 只允许本机 GUI：Electron file:// 页面（Origin: null）与 app:// 自定义协议，
# 外加本机回环开发端口。不再使用允许任意来源的 ['*']。
app.add_middleware(
    CORSMiddleware,
    allow_origins=['null', 'file://', 'app://'],
    allow_origin_regex=r'^(?:https?)://(?:127\.0\.0\.1|localhost|\[::1\])(?::\d+)?$',
    allow_credentials=False,
    allow_methods=['GET', 'POST', 'OPTIONS'],
    allow_headers=['Authorization', 'Content-Type'],
)


def ws_token_valid(websocket: WebSocket) -> bool:
    """WebSocket 无法自定义请求头，改用 ``?token=`` 查询参数鉴权。"""
    return _token_matches(
        websocket.query_params.get(_WS_TOKEN_PARAM),
        resolve_api_token(),
    )


# ═══════════════════════════════════════════════════════════════════════════════
# 5.10：统一错误响应
# ═══════════════════════════════════════════════════════════════════════════════

_VALIDATION_ERROR_MESSAGES = {
    'string_too_short': '字符串长度不足',
    'string_too_long': '字符串长度超限',
    'missing': '缺少必填字段',
    'extra_forbidden': '包含未知字段',
    'int_parsing': '需要整数',
    'float_parsing': '需要数字',
    'bool_parsing': '需要布尔值',
}


def _format_validation_errors(errors: list[dict[str, Any]]) -> str:
    """把 Pydantic 错误列表压成一行可展示文案。"""
    parts: list[str] = []
    for item in errors:
        loc = '.'.join(str(part) for part in item.get('loc', ())) or 'request'
        raw_type = str(item.get('type') or '')
        message = _VALIDATION_ERROR_MESSAGES.get(raw_type)
        if message is None:
            message = str(item.get('msg') or '参数校验失败')
        parts.append(f'{loc}: {message}')
    return '; '.join(parts) or '请求参数校验失败'


def _http_error_message(detail: Any) -> str:
    """从 ``HTTPException.detail`` 提取人类可读文案。"""
    if isinstance(detail, str):
        return detail
    if isinstance(detail, dict):
        for key in ('message', 'error', 'detail'):
            value = detail.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        return json.dumps(detail, ensure_ascii=False)
    if isinstance(detail, list):
        return _format_validation_errors(
            [item for item in detail if isinstance(item, dict)]
        )
    return str(detail)


@app.exception_handler(StarletteHTTPException)
async def _api_http_exception_handler(
    _request: Request,
    exc: StarletteHTTPException,
) -> JSONResponse:
    """把任何 HTTP 异常统一成 ``success=False + error_code`` 结构。

    未显式设置 ``error_code`` 的旧调用点（如框架 404）按状态码兜底，
    前端因此不再需要为每个端点单独判断业务失败。
    """
    detail = exc.detail
    error_code = getattr(exc, 'error_code', None)
    if isinstance(detail, dict):
        error_code = detail.get('error_code') or error_code
    error_code = error_code or fallback_error_code(exc.status_code)
    content = jsonable_encoder(
        {
            'success': False,
            'data': getattr(exc, 'data', None),
            'message': None,
            'error': _http_error_message(detail),
            'error_code': str(error_code),
            'detail': detail,
        }
    )
    return JSONResponse(
        status_code=exc.status_code,
        content=content,
        headers=getattr(exc, 'headers', None),
    )


@app.exception_handler(RequestValidationError)
async def _api_validation_exception_handler(
    _request: Request,
    exc: RequestValidationError,
) -> JSONResponse:
    """422 也走同一错误信封；``detail`` 保留原始错误列表。"""
    errors = jsonable_encoder(exc.errors())
    return JSONResponse(
        status_code=422,
        content={
            'success': False,
            'data': None,
            'message': None,
            'error': _format_validation_errors(errors),
            'error_code': ErrorCode.VALIDATION_ERROR.value,
            'detail': errors,
        },
    )

