# WebSocket 接口
# ═══════════════════════════════════════════════════════════════════════════════


@app.websocket('/ws/logs')
async def ws_logs(websocket: WebSocket):
    """实时日志流（独立连接池）。"""
    if not ws_token_valid(websocket):
        await websocket.close(code=1008)
        return
    await log_ws_manager.connect(websocket)
    try:
        while True:
            data = await websocket.receive_text()
            try:
                msg = json.loads(data)
                if msg.get('type') == 'ping':
                    await websocket.send_text(json.dumps({'type': 'pong'}))
            except json.JSONDecodeError:
                pass
    except WebSocketDisconnect:
        pass
    except Exception as exc:  # noqa: BLE001 - 客户端异常断开也走统一清理
        _log.debug('[WS:logs] 连接异常结束: {}', exc)
    finally:
        await log_ws_manager.disconnect(websocket)


@app.websocket('/ws/task')
async def ws_task(websocket: WebSocket):
    """任务状态更新流（独立连接池）。"""
    if not ws_token_valid(websocket):
        await websocket.close(code=1008)
        return
    await task_ws_manager.connect(websocket)
    try:
        while True:
            data = await websocket.receive_text()
            try:
                msg = json.loads(data)
                if msg.get('type') == 'ping':
                    await websocket.send_text(json.dumps({'type': 'pong'}))
            except json.JSONDecodeError:
                pass
    except WebSocketDisconnect:
        pass
    except Exception as exc:  # noqa: BLE001 - 客户端异常断开也走统一清理
        _log.debug('[WS:task] 连接异常结束: {}', exc)
    finally:
        await task_ws_manager.disconnect(websocket)


